function H({registerIndicator:z,sourceValues:C,nulls:B}){const S=(N,f)=>{const i=N.length,c=new Array(i).fill(NaN),m=new Array(f).fill(NaN);let s=0,n=0,o=0;for(let a=0;a<i;a++){const e=m[s];Number.isFinite(e)&&(o-=e,n-=1);const l=N[a];Number.isFinite(l)?(o+=l,n+=1,m[s]=l):m[s]=NaN,s=(s+1)%f,c[a]=n>0?o/n:NaN}return c},D=(N,f,i)=>{const c=N.length,m=new Array(c).fill(0),s=new Array(f).fill(NaN);let n=0,o=0,a=0;for(let e=0;e<c;e++){const l=Number.isFinite(N[e])?N[e]:0,d=i[e],r=Number.isFinite(d)?l-d:NaN,b=s[n];Number.isFinite(b)&&(a-=b*b,o-=1),Number.isFinite(r)?(a+=r*r,o+=1,s[n]=r):s[n]=NaN,n=(n+1)%f,m[e]=o>1?a/o:0}return m},G=(N,f,i,c,m)=>{const s=N.length,n=new Array(s).fill(NaN),o=new Array(i).fill(NaN),a=new Array(i).fill(NaN);let e=0,l=0,d=0;for(let r=0;r<s;r++){const b=Number.isFinite(N[r])&&Number.isFinite(c[r])?N[r]-c[r]:NaN,g=Number.isFinite(f[r])&&Number.isFinite(m[r])?f[r]-m[r]:NaN,w=o[e],h=a[e];Number.isFinite(w)&&Number.isFinite(h)&&(d-=w*h,l-=1),Number.isFinite(b)&&Number.isFinite(g)?(d+=b*g,l+=1,o[e]=b,a[e]=g):(o[e]=NaN,a[e]=NaN),e=(e+1)%i,n[r]=l>1?d/l:NaN}return n};z({id:"oa-granger",name:"Granger Causality Test (GRANGER)",category:"Statistics",placement:"pane",inputs:[{key:"source1",type:"source",label:"Source 1",default:"close"},{key:"source2",type:"source",label:"Source 2",default:"volume",tooltip:"The source Pine read from another ticker. Only the chart symbol is available here, so pick a second series from it."},{key:"period",type:"number",label:"Period",default:20,min:4,max:5e3,step:1,tooltip:"Lookback for the regressions. The test needs more than three observations for one lag."}],plots:[{key:"fstat",type:"line",title:"F-Stat (X Granger-causes Y)",style:{color:"#ffeb3b",lineWidth:2}}],calc(N,f){const i=Math.max(4,Math.floor(Number(f.period)||20)),c=C(N,f.source1||"close"),m=C(N,f.source2||"volume"),s=N.length,n=new Array(s).fill(NaN),o=new Array(s).fill(NaN);for(let t=1;t<s;t++)n[t]=c[t-1],o[t]=m[t-1];const a=S(c,i),e=S(n,i),l=S(o,i),d=D(n,i,e),r=D(o,i,l),b=G(c,n,i,a,e),g=G(c,o,i,a,l),w=G(n,o,i,e,l);let h=0,E=0,O=0,U=0;const W=new Array(s).fill(NaN);for(let t=0;t<s;t++){const y=d[t],V=r[t],p=w[t],L=b[t],M=g[t];let x=NaN;Number.isFinite(y)&&y>1e-10&&(x=L/y);let q=NaN;Number.isFinite(x)&&(q=a[t]-x*e[t]);let P=NaN;if(Number.isFinite(q)){for(let u=0;u<i;u++){const F=t-u;if(F<0)continue;const Y=c[F],A=n[F];if(!Number.isFinite(Y)||!Number.isFinite(A))continue;const k=Y-(q+x*A);h+=k*k,E+=1}E>1&&(P=h)}let R=NaN,X=NaN,T=NaN;if(Number.isFinite(y)&&Number.isFinite(V)&&Number.isFinite(p)){const u=y*V-p*p;u>1e-10&&Number.isFinite(L)&&Number.isFinite(M)&&(R=(L*V-M*p)/u,X=(M*y-L*p)/u,Number.isFinite(R)&&Number.isFinite(X)&&(T=a[t]-R*e[t]-X*l[t]))}let v=NaN;if(Number.isFinite(T)){for(let u=0;u<i;u++){const F=t-u;if(F<0)continue;const Y=c[F],A=n[F],k=o[F];if(!Number.isFinite(Y)||!Number.isFinite(A)||!Number.isFinite(k))continue;const j=Y-(T+R*A+X*k);O+=j*j,U+=1}U>1&&(v=O)}if(Number.isFinite(P)&&Number.isFinite(v)&&v>1e-10&&i-3>0){const u=(P-v)/(v/(i-3));W[t]=Math.max(0,u)}}return{fstat:B(W)}}})}export{H as default};
